// Probe harness: run the reference executable over a list of cases and record observed behavior.
// Usage: node harness.mjs cases/<name>.json   -> writes observed/<name>.json and prints a table.
// Case file format: JSON array of { a, b, note? } where a/b are the raw CLI strings
//   (either a JSON-encoded value string, or omitted to test missing-arg behavior).
import { spawnSync } from 'node:child_process';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { basename } from 'node:path';

const EXE = '/workspace/dataset/test5_executable';
const file = process.argv[2];
if (!file) {
  console.error('usage: node harness.mjs cases/<name>.json');
  process.exit(2);
}
const cases = JSON.parse(readFileSync(file, 'utf8'));
if (!Array.isArray(cases)) throw new Error('case file must be a JSON array');

const observed = [];
for (const c of cases) {
  const argv = [];
  if (c.argv) argv.push(...c.argv);
  else {
    if (c.a !== undefined) argv.push('--a', c.a);
    if (c.b !== undefined) argv.push('--b', c.b);
  }
  const r = spawnSync(EXE, argv, { encoding: 'utf8', timeout: 30000 });
  observed.push({
    ...c,
    stdout: r.stdout ?? '',
    stderrTail: (r.stderr ?? '').trim().split('\n').slice(-2).join(' | ').slice(0, 300),
    code: r.status,
  });
}

mkdirSync('/workspace/probe/observed', { recursive: true });
const out = `/workspace/probe/observed/${basename(file)}`;
writeFileSync(out, JSON.stringify(observed, null, 1));

for (const o of observed) {
  const res = o.code === 0 ? `out=${JSON.stringify(o.stdout)}` : `EXIT ${o.code}`;
  console.log(
    `${String(o.b).slice(0, 78).padEnd(78)} | ${String(o.a).slice(0, 26).padEnd(26)} => ${res}${o.note ? '   # ' + o.note : ''}`,
  );
}
console.log(`\n${observed.length} cases -> ${out}`);
